  union all
  select 4 as o, '4 disparadores: firmas al registrar (campo y acta), derivadas, firmas definitivas' as k, case when (select count(*) from pg_trigger where not tgisinternal and tgname in ('t_firmas_al_registrar', 't_derivadas_al_registrar', 't_firmas_definitivas', 't_firmas_no_vaciar')) = 5 then 'OK' else 'FALLA' end as estado
